head.b:skin:
/* ============================================================
   UP Outsource Seva Nigam (UPOSN) - Official Blogger Theme
   Optimized for Hindi News, Govt Orders & Employee Information
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --primary: #1e3a8a;       /* Deep Navy */
  --primary-dark: #0f172a;  /* Dark Slate */
  --accent: #d97706;        /* UP Saffron/Amber */
  --danger: #dc2626;        /* Crimson Red / Breaking */
  --bg-light: #f1f5f9;      /* Slate-100 */
  --card-bg: #ffffff;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --font-hindi: 'Noto Sans Devanagari', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-en: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

body {
  background-color: var(--bg-light);
  color: var(--text-main);
  font-family: var(--font-hindi);
  font-size: 15px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 16px;
}

/* ----------------------------------------------------
   Top Micro Bar (Disclaimer & Portal Reference)
   ---------------------------------------------------- */
.uposn-microbar {
  background: #e2e8f0;
  border-bottom: 1px solid #cbd5e1;
  font-size: 12px;
  padding: 5px 0;
  color: #475569;
}
.uposn-microbar-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}
.uposn-badge-independent {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: #1e3a8a;
}
.uposn-microbar-links {
  display: flex;
  align-items: center;
  gap: 12px;
}
.uposn-microbar-links a {
  color: #1e3a8a;
  font-weight: 600;
}
.uposn-microbar-links a:hover {
  text-decoration: underline;
}

/* ----------------------------------------------------
   Main Header & Branding
   ---------------------------------------------------- */
.uposn-header {
  background: #ffffff;
  border-bottom: 2px solid #1e3a8a;
  padding: 12px 0;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.05);
}
.uposn-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.uposn-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
}
.uposn-logo-circle {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: linear-gradient(135deg, #1e3a8a 0%, #0f172a 100%);
  border: 2px solid #f59e0b;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  font-family: var(--font-en);
  font-weight: 800;
  font-size: 16px;
  box-shadow: 0 2px 6px rgba(30, 58, 138, 0.25);
  flex-shrink: 0;
}
.uposn-brand-text h1 {
  font-size: 20px;
  font-weight: 800;
  color: #0f172a;
  line-height: 1.2;
  letter-spacing: -0.02em;
}
.uposn-brand-text h1 span {
  color: #dc2626;
}
.uposn-brand-tagline {
  font-size: 12px;
  color: #475569;
  font-weight: 600;
}

/* Header Search Form */
.uposn-header-search {
  position: relative;
  max-width: 320px;
  width: 100%;
}
.uposn-header-search input {
  width: 100%;
  padding: 9px 14px 9px 36px;
  font-size: 13px;
  font-family: var(--font-hindi);
  border: 1px solid var(--border);
  border-radius: 20px;
  background: #f8fafc;
  color: var(--text-main);
  outline: none;
  transition: all 0.2s;
}
.uposn-header-search input:focus {
  background: #ffffff;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(30, 58, 138, 0.1);
}
.uposn-search-icon {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: #94a3b8;
  pointer-events: none;
  font-size: 14px;
}

/* ----------------------------------------------------
   Navigation Bar
   ---------------------------------------------------- */
.uposn-nav-bar {
  background: #1e3a8a;
  color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 99;
  box-shadow: 0 3px 10px rgba(0,0,0,0.1);
}
.uposn-nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.uposn-nav-links {
  display: flex;
  align-items: center;
  list-style: none;
  overflow-x: auto;
  white-space: nowrap;
  -webkit-overflow-scrolling: touch;
}
.uposn-nav-links::-webkit-scrollbar {
  display: none;
}
.uposn-nav-links li a {
  display: inline-block;
  padding: 12px 16px;
  font-size: 14px;
  font-weight: 700;
  color: #f8fafc;
  transition: background 0.2s;
}
.uposn-nav-links li a:hover,
.uposn-nav-links li a.active {
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
}
.uposn-nav-links li:first-child a {
  background: #dc2626;
}
.uposn-nav-links li:first-child a:hover {
  background: #b91c1c;
}
.uposn-mobile-btn {
  display: none;
  background: transparent;
  border: none;
  color: #ffffff;
  font-size: 20px;
  padding: 10px;
  cursor: pointer;
}

/* ----------------------------------------------------
   Breaking News Ticker
   ---------------------------------------------------- */
.uposn-ticker {
  background: #ffffff;
  border-bottom: 1px solid var(--border);
  padding: 8px 0;
}
.uposn-ticker-inner {
  display: flex;
  align-items: center;
  gap: 12px;
  overflow: hidden;
}
.uposn-ticker-badge {
  background: #dc2626;
  color: #ffffff;
  font-weight: 800;
  font-size: 11px;
  padding: 4px 10px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  flex-shrink: 0;
}
.uposn-ticker-content {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 13px;
  font-weight: 600;
  color: #1e293b;
  flex: 1;
}
.uposn-ticker-content a:hover {
  color: var(--primary);
  text-decoration: underline;
}

/* ----------------------------------------------------
   Main Content & Sidebar Layout
   ---------------------------------------------------- */
.uposn-main-wrapper {
  padding: 24px 0 40px;
}
.uposn-grid-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 992px) {
  .uposn-grid-layout {
    grid-template-columns: 8fr 4fr;
  }
}

/* Section Headings */
.uposn-section-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  padding-bottom: 8px;
  border-bottom: 2px solid #1e3a8a;
}
.uposn-section-title h2,
.uposn-section-title h3 {
  font-size: 18px;
  font-weight: 800;
  color: #0f172a;
  display: flex;
  align-items: center;
  gap: 8px;
}
.uposn-section-title h2::before {
  content: '';
  display: inline-block;
  width: 6px;
  height: 18px;
  background: #dc2626;
  border-radius: 2px;
}

/* ----------------------------------------------------
   Post Cards Grid (Homepage / Search / Archive)
   ---------------------------------------------------- */
.uposn-posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
}
@media (min-width: 640px) {
  .uposn-posts-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.uposn-post-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
}
.uposn-post-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 20px rgba(15, 23, 42, 0.08);
}
.uposn-card-thumb {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #e2e8f0;
  overflow: hidden;
}
.uposn-card-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s;
}
.uposn-post-card:hover .uposn-card-thumb img {
  transform: scale(1.04);
}
.uposn-card-label {
  position: absolute;
  top: 10px;
  left: 10px;
  background: #1e3a8a;
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 4px;
  text-transform: uppercase;
}
.uposn-card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.uposn-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--text-muted);
  margin-bottom: 8px;
}
.uposn-card-title {
  font-size: 16px;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.4;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.uposn-card-title a:hover {
  color: var(--primary);
}
.uposn-card-snippet {
  font-size: 13px;
  color: #475569;
  line-height: 1.5;
  margin-bottom: 12px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  flex: 1;
}
.uposn-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--border);
  font-size: 12px;
  color: var(--primary);
  font-weight: 700;
}

/* ----------------------------------------------------
   Single Article Post View (Post Page)
   ---------------------------------------------------- */
.uposn-single-article {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 24px;
  margin-bottom: 24px;
}
.uposn-article-header {
  margin-bottom: 20px;
}
.uposn-article-category {
  display: inline-block;
  background: #1e3a8a;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 4px;
  margin-bottom: 10px;
}
.uposn-article-title {
  font-size: 24px;
  font-weight: 800;
  line-height: 1.3;
  color: #0f172a;
  margin-bottom: 12px;
}
@media (min-width: 640px) {
  .uposn-article-title {
    font-size: 28px;
  }
}
.uposn-article-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
  padding: 10px 0;
  border-top: 1px solid var(--border);
  border-bottom: 1px solid var(--border);
  font-size: 12px;
  color: var(--text-muted);
}
.uposn-article-featured-img {
  margin: 20px 0;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border);
}
.uposn-article-featured-img img {
  width: 100%;
  max-height: 460px;
  object-fit: cover;
}

/* Share buttons */
.uposn-share-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  background: #f8fafc;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 10px 14px;
  margin-bottom: 20px;
}
.uposn-share-label {
  font-size: 12px;
  font-weight: 700;
  color: #334155;
  margin-right: 4px;
}
.uposn-share-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  color: #ffffff;
  cursor: pointer;
}
.uposn-share-wa { background: #25d366; }
.uposn-share-tg { background: #0088cc; }
.uposn-share-fb { background: #1877f2; }
.uposn-share-tw { background: #0f172a; }

.uposn-article-body {
  font-size: 16px;
  line-height: 1.8;
  color: #1e293b;
}
.uposn-article-body p {
  margin-bottom: 16px;
}
.uposn-article-body h2,
.uposn-article-body h3 {
  color: #0f172a;
  font-weight: 800;
  margin: 24px 0 12px;
}
.uposn-article-body ul,
.uposn-article-body ol {
  margin: 16px 0;
  padding-left: 24px;
}
.uposn-article-body li {
  margin-bottom: 8px;
}
.uposn-article-body blockquote {
  border-left: 4px solid #1e3a8a;
  background: #f8fafc;
  padding: 12px 16px;
  font-style: italic;
  margin: 16px 0;
  color: #334155;
}

/* Official Notice Callout Box */
.uposn-official-box {
  background: #fef2f2;
  border-left: 4px solid #dc2626;
  padding: 14px 18px;
  border-radius: 4px;
  margin: 20px 0;
  font-size: 14px;
}
.uposn-official-box strong {
  color: #991b1b;
}

/* ----------------------------------------------------
   Sidebar Widgets Styling
   ---------------------------------------------------- */
.uposn-sidebar-box {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px;
  margin-bottom: 20px;
}
.uposn-sidebar-box h3 {
  font-size: 16px;
  font-weight: 800;
  color: #0f172a;
  padding-bottom: 8px;
  margin-bottom: 14px;
  border-bottom: 2px solid #1e3a8a;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* Official Portals List */
.uposn-portal-list {
  list-style: none;
}
.uposn-portal-list li {
  padding: 8px 0;
  border-bottom: 1px dashed var(--border);
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.uposn-portal-list li:last-child {
  border-bottom: none;
}
.uposn-portal-list a {
  color: #1e3a8a;
  font-weight: 600;
}
.uposn-portal-list a:hover {
  text-decoration: underline;
}
.uposn-ext-tag {
  background: #e0e7ff;
  color: #3730a3;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
}

/* Join Community Callout */
.uposn-community-callout {
  background: linear-gradient(135deg, #1e3a8a 0%, #0f172a 100%);
  color: #ffffff;
  border-radius: var(--radius-md);
  padding: 18px;
  text-align: center;
  margin-bottom: 20px;
}
.uposn-community-callout h4 {
  font-size: 16px;
  font-weight: 800;
  margin-bottom: 6px;
}
.uposn-community-callout p {
  font-size: 12px;
  color: #cbd5e1;
  margin-bottom: 14px;
}
.uposn-join-btn {
  display: inline-block;
  background: #25d366;
  color: #ffffff;
  font-weight: 800;
  font-size: 13px;
  padding: 8px 16px;
  border-radius: 20px;
  box-shadow: 0 4px 10px rgba(37, 211, 102, 0.3);
}

/* ----------------------------------------------------
   Blogger Comments & Pagination
   ---------------------------------------------------- */
.blog-pager {
  display: flex;
  justify-content: space-between;
  margin: 24px 0;
  padding: 12px 0;
  font-weight: 700;
}
.blog-pager a {
  background: #ffffff;
  border: 1px solid var(--border);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  color: var(--primary);
}
.blog-pager a:hover {
  background: var(--primary);
  color: #ffffff;
}

/* ----------------------------------------------------
   Footer Styling
   ---------------------------------------------------- */
.uposn-footer {
  background: #0f172a;
  color: #cbd5e1;
  padding: 40px 0 20px;
  margin-top: 40px;
  border-top: 3px solid #1e3a8a;
}
.uposn-footer-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  margin-bottom: 30px;
}
@media (min-width: 768px) {
  .uposn-footer-grid {
    grid-template-columns: 2fr 1fr 1fr;
  }
}
.uposn-footer-brand h4 {
  color: #ffffff;
  font-size: 18px;
  font-weight: 800;
  margin-bottom: 10px;
}
.uposn-footer-brand p {
  font-size: 13px;
  line-height: 1.6;
  color: #94a3b8;
}
.uposn-footer-col h5 {
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 12px;
  border-left: 3px solid #f59e0b;
  padding-left: 8px;
}
.uposn-footer-links {
  list-style: none;
}
.uposn-footer-links li {
  margin-bottom: 8px;
  font-size: 13px;
}
.uposn-footer-links a:hover {
  color: #ffffff;
  text-decoration: underline;
}
.uposn-footer-bottom {
  border-top: 1px solid #1e293b;
  padding-top: 18px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
}
.uposn-footer-disclaimer {
  background: rgba(220, 38, 38, 0.1);
  border: 1px solid rgba(220, 38, 38, 0.3);
  color: #fca5a5;
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 11px;
  margin-bottom: 18px;
  text-align: left;
  line-height: 1.5;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
  .uposn-brand-text h1 { font-size: 17px; }
  .uposn-header-search { display: none; }
  .uposn-mobile-btn { display: block; }
  .uposn-nav-links {
    display: none;
    flex-direction: column;
    width: 100%;
    background: #0f172a;
    padding: 10px 0;
  }
  .uposn-nav-links.open { display: flex; }
  .uposn-nav-links li a { width: 100%; padding: 10px 20px; }
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  var mobileBtn = document.getElementById('uposnMobileBtn');
  var navLinks = document.getElementById('uposnNavLinks');
  if (mobileBtn && navLinks) {
    mobileBtn.addEventListener('click', function() {
      navLinks.classList.toggle('open');
    });
  }
});
//
